:root {
  --bg: #0f1115;
  --surface: #181b22;
  --surface-2: #21252e;
  --border: #2b3038;
  --text: #e7eaf0;
  --muted: #9aa3b2;
  --primary: #5b8cff;
  --primary-hover: #6f9bff;
  --danger: #ff6b6b;
  --radius: 12px;
  --shadow: 0 6px 24px rgba(0, 0, 0, 0.35);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 24px;
  background: rgba(15, 17, 21, 0.9);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}

.brand { display: flex; align-items: center; gap: 10px; }
.brand-mark { font-size: 22px; }
.brand h1 { font-size: 18px; margin: 0; letter-spacing: 0.2px; }

.search-wrap { flex: 1; }
#search {
  width: 100%;
  padding: 10px 14px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--text);
  font-size: 14px;
  outline: none;
}
#search:focus { border-color: var(--primary); }

.btn {
  padding: 9px 16px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 14px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
  white-space: nowrap;
}
.btn:hover { background: #2b303b; }
.btn-primary { background: var(--primary); border-color: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-hover); }

.layout {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 24px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
}

.sidebar h2 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  margin: 4px 0 12px;
}
.tag-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.tag-chip {
  width: 100%;
  text-align: left;
  padding: 8px 12px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  font-size: 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.tag-chip:hover { background: var(--surface); }
.tag-chip.active { background: var(--surface-2); color: #fff; }
.tag-count { color: var(--muted); font-size: 12px; }

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: border-color 0.15s, transform 0.15s;
}
.card:hover { border-color: #3a4150; transform: translateY(-2px); }

.card-head { display: flex; align-items: center; gap: 10px; }
.favicon {
  width: 20px; height: 20px; border-radius: 4px; flex-shrink: 0; background: var(--surface-2);
}
.card-title {
  font-weight: 600;
  font-size: 15px;
  color: var(--text);
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.card-title:hover { color: var(--primary-hover); text-decoration: underline; }

.card-url {
  font-size: 12px;
  color: var(--muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.card-desc { font-size: 13px; color: #c3cad6; margin: 0; }

.card-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.card-tag {
  font-size: 11px;
  padding: 3px 9px;
  border-radius: 999px;
  background: var(--surface-2);
  color: #b7c2d6;
  cursor: pointer;
  border: 1px solid var(--border);
}
.card-tag:hover { color: #fff; border-color: var(--primary); }

.card-actions { display: flex; gap: 8px; margin-top: auto; padding-top: 6px; }
.icon-btn {
  background: none;
  border: none;
  color: var(--muted);
  cursor: pointer;
  font-size: 13px;
  padding: 4px 8px;
  border-radius: 6px;
}
.icon-btn:hover { background: var(--surface-2); color: var(--text); }
.icon-btn.danger:hover { color: var(--danger); }

.empty { text-align: center; padding: 80px 20px; color: var(--muted); }
.empty-title { font-size: 18px; color: var(--text); margin: 0 0 6px; }
.empty-sub { margin: 0; }

.status {
  padding: 10px 14px;
  border-radius: 8px;
  margin-bottom: 16px;
  background: rgba(255, 107, 107, 0.12);
  border: 1px solid rgba(255, 107, 107, 0.4);
  color: #ffb4b4;
  font-size: 14px;
}

.dialog {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  padding: 0;
  width: min(480px, 92vw);
  box-shadow: var(--shadow);
}
.dialog::backdrop { background: rgba(0, 0, 0, 0.55); backdrop-filter: blur(2px); }
.dialog form { padding: 24px; display: flex; flex-direction: column; gap: 14px; }
.dialog h2 { margin: 0 0 4px; font-size: 18px; }
.dialog label { display: flex; flex-direction: column; gap: 6px; font-size: 13px; color: var(--muted); }
.dialog input, .dialog textarea {
  padding: 10px 12px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
  resize: vertical;
}
.dialog input:focus, .dialog textarea:focus { outline: none; border-color: var(--primary); }
.dialog-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 8px; }
.form-error {
  margin: 0;
  color: var(--danger);
  font-size: 13px;
}

@media (max-width: 720px) {
  .layout { grid-template-columns: 1fr; }
  .sidebar { order: 2; }
  .topbar { flex-wrap: wrap; }
  .search-wrap { order: 3; flex-basis: 100%; }
}

